        this.name = name;
    }

    String intro() {
        return "本喵叫 " + name;
    }
}

class Student extends Person {
    private int score;

    Student(String name, int score) {
        super(name);
        this.score = score;
    }

    int getScore() { return score; }

    @Override
    String intro() {
        return super.intro() + "，考了 " + score + " 分";
    }
}

